  1	package com.pousada;
  2	
  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousada.api.ApiController;
  7	import com.pousada.infrastructure.Database;
  8	import com.pousada.messaging.MessageProcessor;
  9	import com.pousada.repository.MessageRepository;
 10	import com.pousada.repository.ReservationRepository;
 11	import com.pousada.repository.RoomRepository;
 12	import com.pousada.service.MessageService;
 13	import com.pousada.service.ReportService;
 14	import com.pousada.service.ReservationService;
 15	import com.pousada.service.RoomService;
 16	import io.javalin.Javalin;
 17	import io.javalin.json.JavalinJackson;
 18	
 19	public class Main {
 20	    public static void main(String[] args) {
 21	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 22	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 23	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 24	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 25	        boolean testMode = "true".equalsIgnoreCase(System.getenv("HOTEL_TEST_MODE"));
 26	
 27	        Database database = new Database(dbUrl, dbUser, dbPassword);
 28	
 29	        RoomRepository roomRepository = new RoomRepository(database);
 30	        ReservationRepository reservationRepository = new ReservationRepository(database);
 31	        MessageRepository messageRepository = new MessageRepository(database);
 32	
 33	        MessageProcessor messageProcessor = MessageProcessor.createDefault(testMode);
 34	
 35	        RoomService roomService = new RoomService(roomRepository);
 36	        MessageService messageService = new MessageService(messageRepository, messageProcessor);
 37	        ReservationService reservationService = new ReservationService(
 38	            reservationRepository, roomRepository, messageService
 39	        );
 40	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 41	
 42	        ApiController controller = new ApiController(
 43	            roomService, reservationService, messageService, reportService
 44	        );
 45	
 46	        ObjectMapper objectMapper = new ObjectMapper();
 47	        objectMapper.registerModule(new JavaTimeModule());
 48	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 49	
 50	        Javalin app = Javalin.create(config -> {
 51	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 52	        });
 53	
 54	        app.get("/rooms", controller::getRooms);
 55	        app.post("/reservations", controller::createReservation);
 56	        app.get("/reservations/{id}", controller::getReservation);
 57	        app.post("/reservations/{id}/confirmation", controller::confirmReservation);
 58	        app.post("/reservations/{id}/cancellation", controller::cancelReservation);
 59	        app.post("/reservations/{id}/check-in", controller::checkIn);
 60	        app.post("/reservations/{id}/check-out", controller::checkOut);
 61	        app.get("/reservations/{id}/document", controller::getDocument);
 62	        app.get("/messages", controller::getMessages);
 63	        app.get("/reports/occupancy", controller::getOccupancyReport);
 64	        app.get("/reports/revenue", controller::getRevenueReport);
 65	
 66	        app.exception(Exception.class, (e, ctx) -> {
 67	            e.printStackTrace();
 68	            ctx.status(500).json(new com.pousada.api.ErrorResponse("INTERNAL_ERROR", "Internal server error"));
 69	        });
 70	
 71	        app.start(port);
 72	
 73	        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
 74	            app.stop();
 75	            database.close();
 76	        }));
 77	    }
 78	}
 79	package com.pousada.api;
 80	
 81	import com.fasterxml.jackson.databind.JsonNode;
 82	import com.fasterxml.jackson.databind.ObjectMapper;
 83	import com.fasterxml.jackson.databind.node.ArrayNode;
 84	import com.pousada.domain.Message;
 85	import com.pousada.domain.Reservation;
 86	import com.pousada.domain.Room;
 87	import com.pousada.service.MessageService;
 88	import com.pousada.service.ReportService;
 89	import com.pousada.service.ReservationService;
 90	import com.pousada.service.RoomService;
 91	import io.javalin.http.Context;
 92	
 93	import java.time.LocalDate;
 94	import java.time.YearMonth;
 95	import java.time.format.DateTimeParseException;
 96	import java.util.List;
 97	
 98	public class ApiController {
 99	    private final RoomService roomService;
100	    private final ReservationService reservationService;
101	    private final MessageService messageService;
102	    private final ReportService reportService;
103	    private final ObjectMapper mapper = new ObjectMapper();
104	
105	    public ApiController(RoomService roomService, ReservationService reservationService,
106	                        MessageService messageService, ReportService reportService) {
107	        this.roomService = roomService;
108	        this.reservationService = reservationService;
109	        this.messageService = messageService;
110	        this.reportService = reportService;
111	    }
112	
113	    public void getRooms(Context ctx) {
114	        List<Room> rooms = roomService.getAllRooms();
115	        ArrayNode json = mapper.createArrayNode();
116	        for (Room room : rooms) {
117	            json.add(ApiMappers.toRoomJson(room));
118	        }
119	        ctx.json(json);
120	    }
121	
122	    public void createReservation(Context ctx) {
123	        try {
124	            JsonNode body = mapper.readTree(ctx.body());
125	
126	            String roomNumber = getRequiredString(body, "roomNumber");
127	            String guestName = getRequiredString(body, "guestName");
128	            String guestEmail = getRequiredString(body, "guestEmail");
129	            String guestCpf = getRequiredString(body, "guestCpf");
130	            LocalDate checkIn = getRequiredDate(body, "checkIn");
131	            LocalDate checkOut = getRequiredDate(body, "checkOut");
132	            int guests = getRequiredInt(body, "guests");
133	            String ratePlan = getRequiredString(body, "ratePlan");
134	
135	            Reservation reservation = reservationService.createReservation(
136	                roomNumber, guestName, guestEmail, guestCpf,
137	                checkIn, checkOut, guests, ratePlan
138	            );
139	
140	            ctx.status(201).json(ApiMappers.toReservationJson(reservation));
141	        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
142	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid JSON"));
143	        } catch (InvalidRequestException e) {
144	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
145	        } catch (ReservationService.RoomNotFoundException e) {
146	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
147	        } catch (ReservationService.RoomUnavailableException e) {
148	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the selected dates"));
149	        } catch (ReservationService.CapacityExceededException e) {
150	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
151	        }
152	    }
153	
154	    public void getReservation(Context ctx) {
155	        try {
156	            Long id = Long.parseLong(ctx.pathParam("id"));
157	            Reservation reservation = reservationService.getReservation(id)
158	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException());
159	            ctx.json(ApiMappers.toReservationJson(reservation));
160	        } catch (ReservationService.ReservationNotFoundException e) {
161	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
162	        }
163	    }
164	
165	    public void confirmReservation(Context ctx) {
166	        try {
167	            Long id = Long.parseLong(ctx.pathParam("id"));
168	            Reservation reservation = reservationService.confirmReservation(id);
169	            ctx.json(ApiMappers.toReservationJson(reservation));
170	        } catch (ReservationService.ReservationNotFoundException e) {
171	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
172	        } catch (ReservationService.OperationNotAllowedException e) {
173	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation status"));
174	        }
175	    }
176	
177	    public void cancelReservation(Context ctx) {
178	        try {
179	            Long id = Long.parseLong(ctx.pathParam("id"));
180	            Reservation reservation = reservationService.cancelReservation(id);
181	            ctx.json(ApiMappers.toReservationJson(reservation));
182	        } catch (ReservationService.ReservationNotFoundException e) {
183	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
184	        } catch (ReservationService.OperationNotAllowedException e) {
185	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation status"));
186	        }
187	    }
188	
189	    public void checkIn(Context ctx) {
190	        try {
191	            Long id = Long.parseLong(ctx.pathParam("id"));
192	            Reservation reservation = reservationService.checkIn(id);
193	            ctx.json(ApiMappers.toReservationJson(reservation));
194	        } catch (ReservationService.ReservationNotFoundException e) {
195	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
196	        } catch (ReservationService.OperationNotAllowedException e) {
197	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation status"));
198	        }
199	    }
200	
201	    public void checkOut(Context ctx) {
202	        try {
203	            Long id = Long.parseLong(ctx.pathParam("id"));
204	            Reservation reservation = reservationService.checkOut(id);
205	
206	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
207	            String document = messageService.formatDocument(reservation, room.getType().name());
208	
209	            ctx.json(ApiMappers.toDocumentJson(reservation, room.getType().name(), document));
210	        } catch (ReservationService.ReservationNotFoundException e) {
211	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
212	        } catch (ReservationService.OperationNotAllowedException e) {
213	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed in current reservation status"));
214	        }
215	    }
216	
217	    public void getDocument(Context ctx) {
218	        try {
219	            Long id = Long.parseLong(ctx.pathParam("id"));
220	            Reservation reservation = reservationService.getReservation(id)
221	                .orElseThrow(() -> new ReservationService.ReservationNotFoundException());
222	
223	            if (!reservation.isPaid()) {
224	                ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Document only available for paid reservations"));
225	                return;
226	            }
227	
228	            Room room = roomService.getRoomByNumber(reservation.getRoomNumber()).orElseThrow();
229	            String document = messageService.formatDocument(reservation, room.getType().name());
230	
231	            ctx.json(ApiMappers.toDocumentJson(reservation, room.getType().name(), document));
232	        } catch (ReservationService.ReservationNotFoundException e) {
233	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
234	        }
235	    }
236	
237	    public void getMessages(Context ctx) {
238	        List<Message> messages = messageService.getAllMessages();
239	        ArrayNode json = mapper.createArrayNode();
240	        for (Message message : messages) {
241	            json.add(ApiMappers.toMessageJson(message));
242	        }
243	        ctx.json(json);
244	    }
245	
246	    public void getOccupancyReport(Context ctx) {
247	        try {
248	            String dateStr = ctx.queryParam("date");
249	            if (dateStr == null || dateStr.isEmpty()) {
250	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Date parameter is required"));
251	                return;
252	            }
253	
254	            LocalDate date = LocalDate.parse(dateStr);
255	            String csv = reportService.generateOccupancyReport(date);
256	
257	            ctx.contentType("text/csv; charset=utf-8").result(csv);
258	        } catch (DateTimeParseException e) {
259	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
260	        }
261	    }
262	
263	    public void getRevenueReport(Context ctx) {
264	        try {
265	            String monthStr = ctx.queryParam("month");
266	            if (monthStr == null || monthStr.isEmpty()) {
267	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Month parameter is required"));
268	                return;
269	            }
270	
271	            YearMonth month = YearMonth.parse(monthStr);
272	            String csv = reportService.generateRevenueReport(month);
273	
274	            ctx.contentType("text/csv; charset=utf-8").result(csv);
275	        } catch (DateTimeParseException e) {
276	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid month format"));
277	        }
278	    }
279	
280	    private String getRequiredString(JsonNode body, String field) {
281	        if (!body.has(field) || body.get(field).isNull()) {
282	            throw new InvalidRequestException("Missing required field: " + field);
283	        }
284	        return body.get(field).asText();
285	    }
286	
287	    private int getRequiredInt(JsonNode body, String field) {
288	        if (!body.has(field) || body.get(field).isNull()) {
289	            throw new InvalidRequestException("Missing required field: " + field);
290	        }
291	        return body.get(field).asInt();
292	    }
293	
294	    private LocalDate getRequiredDate(JsonNode body, String field) {
295	        String dateStr = getRequiredString(body, field);
296	        try {
297	            return LocalDate.parse(dateStr);
298	        } catch (DateTimeParseException e) {
299	            throw new InvalidRequestException("Invalid date format for field: " + field);
300	        }
301	    }
302	
303	    public static class InvalidRequestException extends RuntimeException {
304	        public InvalidRequestException(String message) {
305	            super(message);
306	        }
307	    }
308	}
