311	import com.fasterxml.jackson.databind.JsonNode;
312	import com.fasterxml.jackson.databind.ObjectMapper;
313	import com.fasterxml.jackson.databind.node.ObjectNode;
314	import com.pousada.domain.Message;
315	import com.pousada.domain.Reservation;
316	import com.pousada.domain.Room;
317	
318	import java.time.format.DateTimeFormatter;
319	
320	public class ApiMappers {
321	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
322	    private static final ObjectMapper mapper = new ObjectMapper();
323	
324	    public static JsonNode toRoomJson(Room room) {
325	        ObjectNode json = mapper.createObjectNode();
326	        json.put("number", room.getNumber());
327	        json.put("type", room.getType().name());
328	        json.put("capacity", room.getCapacity());
329	        json.put("nightlyRate", room.getNightlyRate());
330	        return json;
331	    }
332	
333	    public static JsonNode toReservationJson(Reservation reservation) {
334	        ObjectNode json = mapper.createObjectNode();
335	        json.put("id", reservation.getId());
336	        json.put("roomNumber", reservation.getRoomNumber());
337	        json.put("guestName", reservation.getGuestName());
338	        json.put("guestEmail", reservation.getGuestEmail());
339	        json.put("guestCpf", reservation.getGuestCpf());
340	        json.put("checkIn", reservation.getCheckIn().format(DATE_FORMAT));
341	        json.put("checkOut", reservation.getCheckOut().format(DATE_FORMAT));
342	        json.put("guests", reservation.getGuests());
343	        json.put("ratePlan", reservation.getRatePlan().name());
344	        json.put("nights", reservation.getNights());
345	        json.put("subtotal", reservation.getSubtotal());
346	        json.put("discount", reservation.getDiscount());
347	        json.put("total", reservation.getTotal());
348	        json.put("status", reservation.getStatus().name());
349	        json.put("amountPaid", reservation.getAmountPaid());
350	        if (reservation.getRefund() != null) {
351	            json.put("refund", reservation.getRefund());
352	        } else {
353	            json.putNull("refund");
354	        }
355	        return json;
356	    }
357	
358	    public static JsonNode toMessageJson(Message message) {
359	        ObjectNode json = mapper.createObjectNode();
360	        json.put("id", message.getId());
361	        json.put("channel", message.getChannel().name());
362	        json.put("to", message.getTo());
363	        json.put("subject", message.getSubject());
364	        json.put("body", message.getBody());
365	        json.put("status", message.getStatus().name());
366	        return json;
367	    }
368	
369	    public static JsonNode toDocumentJson(Reservation reservation, String roomType, String documentText) {
370	        ObjectNode json = mapper.createObjectNode();
371	        json.put("title", "Comprovante de reserva");
372	        json.put("reservationId", reservation.getId());
373	        json.put("guestName", reservation.getGuestName());
374	        json.put("guestCpf", reservation.getGuestCpf());
375	        json.put("roomNumber", reservation.getRoomNumber());
376	        json.put("roomType", roomType);
377	        json.put("checkIn", reservation.getCheckIn().format(DATE_FORMAT));
378	        json.put("checkOut", reservation.getCheckOut().format(DATE_FORMAT));
379	        json.put("nights", reservation.getNights());
380	        json.put("subtotal", reservation.getSubtotal());
381	        json.put("discount", reservation.getDiscount());
382	        json.put("total", reservation.getTotal());
383	        return json;
384	    }
385	}
