 15	public class MessageService {
 16	    private final MessageRepository messageRepository;
 17	    private final MessageProcessor messageProcessor;
 18	    private static final Locale BRAZIL = Locale.of("pt", "BR");
 19	    private static final NumberFormat CURRENCY_FORMAT = NumberFormat.getCurrencyInstance(BRAZIL);
 20	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
