 22	    public MessageService(MessageRepository messageRepository, MessageProcessor messageProcessor) {
 23	        this.messageRepository = messageRepository;
 24	        this.messageProcessor = messageProcessor;
 25	    }
 26	
 27	    public void sendConfirmationEmail(Reservation reservation, String document) {
 28	        String subject = "Reserva confirmada - Pousada Maré Alta";
 29	        String body = String.format("""
 30	            Olá, %s!
 31	
 32	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
 33	
 34	            %s
 35	
 36	            A entrada é a partir das 14h, e a saída, até as 12h.
 37	            Até breve!
 38	            """, reservation.getGuestName(), document);
 39	
 40	        Message message = new Message(
 41	            MessageChannel.EMAIL,
 42	            reservation.getGuestEmail(),
 43	            subject,
 44	            body,
 45	            MessageStatus.SENT
 46	        );
 47	
 48	        List<Message> processedMessages = messageProcessor.process(message);
 49	        for (Message msg : processedMessages) {
 50	            messageRepository.save(msg);
 51	        }
 52	    }
