 58	    public String formatDocument(Reservation reservation, String roomType) {
 59	        StringBuilder doc = new StringBuilder();
 60	        doc.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
 61	        doc.append("Hóspede: ").append(reservation.getGuestName())
 62	           .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
 63	        doc.append("Quarto: ").append(reservation.getRoomNumber())
 64	           .append(" (").append(roomType).append(")\n");
 65	        doc.append("Entrada: ").append(reservation.getCheckIn().format(DATE_FORMAT))
 66	           .append(" | Saída: ").append(reservation.getCheckOut().format(DATE_FORMAT))
 67	           .append(" | ").append(reservation.getNights())
 68	           .append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
 69	        doc.append("Diárias: ").append(formatCurrency(reservation.getSubtotal())).append("\n");
 70	
 71	        if (reservation.getDiscount().compareTo(java.math.BigDecimal.ZERO) > 0) {
 72	            doc.append("Desconto: ").append(formatCurrency(reservation.getDiscount())).append("\n");
 73	        }
 74	
 75	        doc.append("Total: ").append(formatCurrency(reservation.getTotal()));
 76	
 77	        return doc.toString();
 78	    }
 79	
 80	    private String formatCpf(String cpf) {
 81	        if (cpf.length() == 11) {
 82	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
 83	                   cpf.substring(6, 9) + "-" + cpf.substring(9, 11);
 84	        }
 85	        return cpf;
 86	    }
 87	
 88	    private String formatCurrency(java.math.BigDecimal amount) {
 89	        return CURRENCY_FORMAT.format(amount);
 90	    }
 91	}
