136	    public String generateRevenueReport(YearMonth month) {
137	        List<Reservation> reservations = reservationRepository.findByMonthAndRevenue(month);
138	
139	        StringBuilder csv = new StringBuilder();
140	        csv.append("reservation,room,check_in,check_out,status,amount\n");
141	
142	        BigDecimal total = BigDecimal.ZERO;
143	
144	        for (Reservation reservation : reservations) {
145	            BigDecimal revenue = reservation.getAmountPaid();
146	            if (reservation.getRefund() != null) {
147	                revenue = revenue.subtract(reservation.getRefund());
148	            }
149	
150	            if (revenue.compareTo(BigDecimal.ZERO) > 0) {
151	                csv.append(reservation.getId()).append(",")
152	                   .append(reservation.getRoomNumber()).append(",")
153	                   .append(reservation.getCheckIn().format(DATE_FORMAT)).append(",")
154	                   .append(reservation.getCheckOut().format(DATE_FORMAT)).append(",")
155	                   .append(reservation.getStatus().name()).append(",")
156	                   .append(revenue.toString()).append("\n");
157	
158	                total = total.add(revenue);
159	            }
160	        }
161	
162	        csv.append("total,").append(total.toString());
163	
164	        return csv.toString();
165	    }
