179	
180	public class ReservationService {
181	    private final ReservationRepository reservationRepository;
182	    private final RoomRepository roomRepository;
183	    private final MessageService messageService;
184	
185	    public ReservationService(ReservationRepository reservationRepository,
186	                            RoomRepository roomRepository,
187	                            MessageService messageService) {
188	        this.reservationRepository = reservationRepository;
189	        this.roomRepository = roomRepository;
190	        this.messageService = messageService;
191	    }
192	
193	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
194	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
195	                                        int guests, String ratePlanStr) {
196	        Room room = roomRepository.findByNumber(roomNumber)
197	            .orElseThrow(() -> new RoomNotFoundException());
198	
199	        if (guests > room.getCapacity()) {
200	            throw new CapacityExceededException();
201	        }
202	
203	        if (guests < 1) {
204	            throw new InvalidRequestException("At least one guest is required");
205	        }
206	
207	        if (!checkOut.isAfter(checkIn)) {
208	            throw new InvalidRequestException("Check-out must be after check-in");
209	        }
210	
211	        List<Reservation> conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut);
212	        if (!conflicts.isEmpty()) {
213	            throw new RoomUnavailableException();
214	        }
215	
216	        com.pousada.domain.RatePlan ratePlan;
217	        try {
218	            ratePlan = com.pousada.domain.RatePlan.valueOf(ratePlanStr);
219	        } catch (IllegalArgumentException e) {
220	            throw new InvalidRequestException("Invalid rate plan");
221	        }
222	
223	        Reservation reservation = new Reservation(
224	            roomNumber, guestName, guestEmail, guestCpf,
225	            checkIn, checkOut, guests, ratePlan
226	        );
227	
228	        BigDecimal subtotal = calculateSubtotal(reservation, room);
229	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate())
230	            .setScale(2, RoundingMode.HALF_EVEN);
231	        BigDecimal total = subtotal.subtract(discount);
232	
233	        reservation.setAmountPaid(BigDecimal.ZERO);
234	
235	        return reservationRepository.save(reservation);
236	    }
237	
238	    private BigDecimal calculateSubtotal(Reservation reservation, Room room) {
239	        BigDecimal subtotal = BigDecimal.ZERO;
240	        LocalDate current = reservation.getCheckIn();
241	
242	        while (current.isBefore(reservation.getCheckOut())) {
243	            BigDecimal nightPrice = reservation.calculateNightPrice(current, room.getNightlyRate());
244	            subtotal = subtotal.add(nightPrice);
245	            current = current.plusDays(1);
246	        }
247	
248	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
249	    }
250	
251	    public Optional<Reservation> getReservation(Long id) {
252	        return reservationRepository.findById(id);
253	    }
254	
255	    public Reservation confirmReservation(Long id) {
256	        Reservation reservation = reservationRepository.findById(id)
257	            .orElseThrow(() -> new ReservationNotFoundException());
258	
259	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
260	            .orElseThrow(() -> new RoomNotFoundException());
261	
262	        BigDecimal subtotal = calculateSubtotal(reservation, room);
263	        BigDecimal discount = subtotal.multiply(reservation.getRatePlan().getDiscountRate())
264	            .setScale(2, RoundingMode.HALF_EVEN);
265	        BigDecimal total = subtotal.subtract(discount);
266	
267	        try {
268	            reservation.confirm(subtotal, total);
269	        } catch (IllegalStateException e) {
270	            throw new OperationNotAllowedException();
271	        }
272	
273	        reservation.setRefund(BigDecimal.ZERO);
274	
275	        reservation = reservationRepository.save(reservation);
276	
277	        String document = messageService.formatDocument(reservation, room.getType().name());
278	        messageService.sendConfirmationEmail(reservation, document);
279	
280	        return reservation;
281	    }
282	
283	    public Reservation cancelReservation(Long id) {
284	        Reservation reservation = reservationRepository.findById(id)
285	            .orElseThrow(() -> new ReservationNotFoundException());
286	
287	        try {
288	            reservation.cancel();
289	        } catch (IllegalStateException e) {
290	            throw new OperationNotAllowedException();
291	        }
292	
293	        return reservationRepository.save(reservation);
294	    }
295	
296	    public Reservation checkIn(Long id) {
297	        Reservation reservation = reservationRepository.findById(id)
298	            .orElseThrow(() -> new ReservationNotFoundException());
299	
300	        try {
301	            reservation.checkIn();
302	        } catch (IllegalStateException e) {
303	            throw new OperationNotAllowedException();
304	        }
305	
306	        return reservationRepository.save(reservation);
307	    }
308	
309	    public Reservation checkOut(Long id) {
310	        Reservation reservation = reservationRepository.findById(id)
311	            .orElseThrow(() -> new ReservationNotFoundException());
312	
313	        try {
314	            reservation.checkOut();
315	        } catch (IllegalStateException e) {
316	            throw new OperationNotAllowedException();
317	        }
318	
319	        return reservationRepository.save(reservation);
320	    }
