100	    private BigDecimal refund;
101	
102	    public Reservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
103	                      LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
104	        this.roomNumber = roomNumber;
105	        this.guestName = guestName;
106	        this.guestEmail = guestEmail;
107	        this.guestCpf = guestCpf;
108	        this.checkIn = checkIn;
109	        this.checkOut = checkOut;
110	        this.guests = guests;
111	        this.ratePlan = ratePlan;
112	        this.status = ReservationStatus.PENDING;
113	        this.subtotal = BigDecimal.ZERO;
114	        this.amountPaid = BigDecimal.ZERO;
115	        this.refund = null;
116	    }
