162	    public void confirm(BigDecimal subtotalValue, BigDecimal totalValue) {
163	        if (status != ReservationStatus.PENDING) {
164	            throw new IllegalStateException("Can only confirm pending reservations");
165	        }
166	        this.status = ReservationStatus.CONFIRMED;
167	        this.subtotal = subtotalValue;
168	        this.amountPaid = totalValue;
169	    }
170	
171	    public void setSubtotal(BigDecimal subtotal) {
172	        this.subtotal = subtotal;
173	    }
174	
175	    public void checkIn() {
176	        if (status != ReservationStatus.CONFIRMED) {
177	            throw new IllegalStateException("Can only check in confirmed reservations");
178	        }
179	        this.status = ReservationStatus.CHECKED_IN;
180	    }
181	
182	    public void checkOut() {
183	        if (status != ReservationStatus.CHECKED_IN) {
184	            throw new IllegalStateException("Can only check out checked-in reservations");
185	        }
186	        this.status = ReservationStatus.CHECKED_OUT;
187	    }
188	
189	    public void cancel() {
190	        if (status != ReservationStatus.PENDING && status != ReservationStatus.CONFIRMED) {
191	            throw new IllegalStateException("Can only cancel pending or confirmed reservations");
192	        }
193	        this.status = ReservationStatus.CANCELLED;
194	
195	        if (ratePlan == RatePlan.STANDARD && amountPaid.compareTo(BigDecimal.ZERO) > 0) {
196	            this.refund = amountPaid;
197	            this.amountPaid = BigDecimal.ZERO;
198	        } else {
199	            this.refund = BigDecimal.ZERO;
200	        }
201	    }
202	
203	    public boolean isPaid() {
204	        return status == ReservationStatus.CONFIRMED ||
