340	public class BlockInvalidEmailPolicy implements MessagePolicy {
341	
342	    @Override
343	    public void apply(PolicyResult result) {
344	        Message message = result.getMessage();
345	        if (!isValidEmail(message.getTo())) {
346	            result.transform(PolicyResult.block(message).getMessage());
347	        }
348	    }
349	
350	    private boolean isValidEmail(String email) {
351	        if (email == null || email.isEmpty()) {
352	            return false;
353	        }
354	
355	        long atCount = email.chars().filter(ch -> ch == '@').count();
356	        if (atCount != 1) {
357	            return false;
358	        }
359	
360	        int atIndex = email.indexOf('@');
361	        if (atIndex == 0) {
362	            return false;
363	        }
364	
365	        String afterAt = email.substring(atIndex + 1);
366	        if (afterAt.isEmpty() || !afterAt.contains(".")) {
367	            return false;
368	        }
369	
370	        return true;
371	    }
372	}
