122	    public BigDecimal calculateNightPrice(LocalDate date, BigDecimal baseRate) {
123	        BigDecimal price = baseRate;
124	        if (isHighSeason(date)) {
125	            BigDecimal highSeasonMultiplier = new BigDecimal("1.20");
126	            price = price.multiply(highSeasonMultiplier).setScale(2, RoundingMode.HALF_EVEN);
127	        }
128	        return price;
129	    }
130	
131	    private boolean isHighSeason(LocalDate date) {
132	        Month month = date.getMonth();
133	        int day = date.getDayOfMonth();
134	
135	        if (month == Month.DECEMBER && day >= 15) {
136	            return true;
137	        }
138	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
139	            return true;
140	        }
141	        if (month == Month.JULY) {
142	            return true;
143	        }
144	        return false;
145	    }
