  8	import java.sql.Connection;
  9	import java.sql.PreparedStatement;
 10	import java.sql.ResultSet;
 11	import java.sql.SQLException;
 12	import java.util.ArrayList;
 13	import java.util.List;
 14	
 15	public class MessageRepository {
 16	    private final Database database;
 17	
 18	    public MessageRepository(Database database) {
 19	        this.database = database;
 20	    }
 21	
 22	    public Message save(Message message) {
 23	        String sql = """
 24	            INSERT INTO messages (channel, recipient, subject, body, status)
 25	            VALUES (?, ?, ?, ?, ?)
 26	            RETURNING id
 27	            """;
 28	
 29	        try (Connection conn = database.getConnection();
 30	             PreparedStatement stmt = conn.prepareStatement(sql)) {
 31	
 32	            stmt.setString(1, message.getChannel().name());
 33	            stmt.setString(2, message.getTo());
 34	            stmt.setString(3, message.getSubject());
 35	            stmt.setString(4, message.getBody());
 36	            stmt.setString(5, message.getStatus().name());
 37	
 38	            try (ResultSet rs = stmt.executeQuery()) {
 39	                if (rs.next()) {
 40	                    message.setId(rs.getLong("id"));
 41	                }
 42	            }
 43	
 44	            return message;
 45	        } catch (SQLException e) {
 46	            throw new RuntimeException("Failed to save message", e);
 47	        }
 48	    }
 49	
 50	    public List<Message> findAll() {
 51	        List<Message> messages = new ArrayList<>();
 52	        String sql = """
 53	            SELECT id, channel, recipient, subject, body, status
 54	            FROM messages
 55	            ORDER BY id
 56	            """;
 57	
 58	        try (Connection conn = database.getConnection();
 59	             PreparedStatement stmt = conn.prepareStatement(sql);
 60	             ResultSet rs = stmt.executeQuery()) {
 61	
 62	            while (rs.next()) {
 63	                Message message = new Message(
 64	                    MessageChannel.valueOf(rs.getString("channel")),
 65	                    rs.getString("recipient"),
 66	                    rs.getString("subject"),
 67	                    rs.getString("body"),
 68	                    MessageStatus.valueOf(rs.getString("status"))
 69	                );
 70	                message.setId(rs.getLong("id"));
 71	                messages.add(message);
 72	            }
 73	        } catch (SQLException e) {
 74	            throw new RuntimeException("Failed to fetch messages", e);
 75	        }
 76	
 77	        return messages;
 78	    }
 79	}
