423	        String createRoomsTable = """
424	            CREATE TABLE IF NOT EXISTS rooms (
425	                number VARCHAR(10) PRIMARY KEY,
426	                type VARCHAR(20) NOT NULL
427	            )
428	            """;
429	
430	        String createReservationsTable = """
431	            CREATE TABLE IF NOT EXISTS reservations (
432	                id SERIAL PRIMARY KEY,
433	                room_number VARCHAR(10) NOT NULL REFERENCES rooms(number),
434	                guest_name VARCHAR(255) NOT NULL,
435	                guest_email VARCHAR(255) NOT NULL,
436	                guest_cpf VARCHAR(14) NOT NULL,
437	                check_in DATE NOT NULL,
438	                check_out DATE NOT NULL,
439	                guests INTEGER NOT NULL,
440	                rate_plan VARCHAR(20) NOT NULL,
441	                status VARCHAR(20) NOT NULL,
442	                subtotal DECIMAL(10, 2) NOT NULL,
443	                amount_paid DECIMAL(10, 2) NOT NULL,
444	                refund DECIMAL(10, 2)
445	            )
446	            """;
447	
448	        String createMessagesTable = """
449	            CREATE TABLE IF NOT EXISTS messages (
450	                id SERIAL PRIMARY KEY,
451	                channel VARCHAR(20) NOT NULL,
452	                recipient VARCHAR(255) NOT NULL,
453	                subject TEXT NOT NULL,
454	                body TEXT NOT NULL,
455	                status VARCHAR(20) NOT NULL
456	            )
457	            """;
