461	                ('101', 'STANDARD'),
462	                ('102', 'STANDARD'),
463	                ('201', 'DELUXE'),
464	                ('202', 'DELUXE'),
465	                ('301', 'SUITE')
466	            ON CONFLICT (number) DO NOTHING
467	            """;
468	
469	        try (Connection conn = dataSource.getConnection();
470	             Statement stmt = conn.createStatement()) {
471	            stmt.execute(createRoomsTable);
472	            stmt.execute(createReservationsTable);
473	            stmt.execute(createMessagesTable);
474	            stmt.execute(insertRooms);
475	        } catch (SQLException e) {
476	            throw new RuntimeException("Failed to initialize database schema", e);
477	        }
478	    }
